import re
from datetime import datetime


def dedupe_contacts(rows):
    GMAIL = {"gmail.com", "googlemail.com"}
    OPT_YES = {"y", "yes", "true", "1"}
    DATE_FORMATS = ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y")

    def s(v):
        return "" if v is None else str(v)

    def norm_email(raw):
        e = s(raw)
        m = re.search(r"<([^>]*)>", e)
        if m:
            e = m.group(1)
        e = e.strip().lower()
        if e.count("@") == 1:
            local, domain = e.split("@")
            if domain in GMAIL:
                local = local.replace(".", "").split("+")[0]
                domain = "gmail.com"
            e = local + "@" + domain
        # validity
        if e.count("@") != 1:
            return ""
        local, domain = e.split("@")
        if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""
        return e

    def norm_phone(raw):
        p = s(raw)
        m = re.search(r"ext|x|#", p, flags=re.IGNORECASE)
        if m:
            p = p[:m.start()]
        d = re.sub(r"[^0-9]", "", p)
        if len(d) == 11 and d[0] == "1":
            d = d[1:]
        if len(d) == 10 and d[0] not in "01":
            return d
        return ""

    def norm_zip(raw):
        z = s(raw).strip()
        m = re.fullmatch(r"([0-9]{5})-([0-9]{4})", z)
        if m:
            z = m.group(1)
        if re.fullmatch(r"[0-9]{4}", z):
            z = "0" + z
        if re.fullmatch(r"[0-9]{5}", z):
            return z
        return ""

    def norm_name(raw):
        n = s(raw).strip()
        if n.isupper() or n.islower():
            n = n.title()
        return n

    def parse_date(raw):
        v = s(raw).strip()
        for f in DATE_FORMATS:
            try:
                return datetime.strptime(v, f)
            except ValueError:
                pass
        return datetime.min

    def split_tags(raw):
        out = []
        for t in re.split(r"[;,]", s(raw)):
            t = t.strip().lower()
            if t:
                out.append(t)
        return out

    # Normalize and filter
    recs = []
    for idx, r in enumerate(rows):
        email = norm_email(r.get("email"))
        phone = norm_phone(r.get("phone"))
        if not email and not phone:
            continue
        source = s(r.get("source")).strip().lower()
        recs.append({
            "idx": idx,
            "first_name": norm_name(r.get("first_name")),
            "last_name": norm_name(r.get("last_name")),
            "zip": norm_zip(r.get("zip")),
            "email": email,
            "phone": phone,
            "source": source,
            "manual": source == "manual",
            "tags": split_tags(r.get("tags")),
            "opted_out": s(r.get("opted_out")).strip().lower() in OPT_YES,
            "updated": parse_date(r.get("updated")),
        })

    n = len(recs)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    email_seen = {}
    phone_last_seen = {}
    for i, rec in enumerate(recs):
        if rec["email"]:
            k = rec["email"]
            if k in email_seen:
                union(i, email_seen[k])
            else:
                email_seen[k] = i
        last = rec["last_name"].lower()
        if rec["phone"] and last:
            k = (rec["phone"], last)
            if k in phone_last_seen:
                union(i, phone_last_seen[k])
            else:
                phone_last_seen[k] = i

    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)

    def sort_key(rec):
        return (0 if rec["manual"] else 1,
                -(rec["updated"] - datetime.min).total_seconds(),
                rec["idx"])

    def pick(members, field):
        cands = [m for m in members if m[field]]
        if not cands:
            return ""
        return min(cands, key=sort_key)[field]

    result = []
    for members_idx in sorted(groups.values(), key=lambda g: min(recs[i]["idx"] for i in g)):
        members = [recs[i] for i in members_idx]
        tags = set()
        for m in members:
            tags.update(m["tags"])
        latest = max(m["updated"] for m in members)
        result.append({
            "first_name": pick(members, "first_name"),
            "last_name": pick(members, "last_name"),
            "zip": pick(members, "zip"),
            "email": pick(members, "email"),
            "phone": pick(members, "phone"),
            "source": pick(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(m["opted_out"] for m in members) else "N",
            "updated": "%04d-%02d-%02d" % (latest.year, latest.month, latest.day),
        })
    return result
